use std::collections::HashMap;
use std::cell::RefCell;

/// Secure memory pool for sensitive data (keys, tokens, etc.)
/// Uses custom allocation to avoid sensitive data in standard heap
pub struct SecurePool {
    /// Each slab is a fixed-size region
    slabs: RefCell<Vec<Vec<u8>>>,
    /// Maps allocation ID -> (slab_index, offset, length)
    allocations: RefCell<HashMap<u64, (usize, usize, usize)>>,
    /// Slab size in bytes
    slab_size: usize,
    /// Next allocation ID
    next_id: RefCell<u64>,
    /// Audit logger - called on every alloc/free for compliance
    audit_log: Box<dyn Fn(u64, &str)>,
}

/// Header stored before each allocation within a slab
#[repr(C)]
struct AllocHeader {
    /// Magic number for corruption detection
    magic: u32,
    /// Size of the user data following this header
    user_size: u32,
    /// Allocation ID for cross-referencing
    alloc_id: u32,
    /// Padding/alignment field
    flags: u32,
}

const HEADER_SIZE: usize = std::mem::size_of::<AllocHeader>();
const MAGIC: u32 = 0xDEAD_BEEF;
const MAX_ALLOC_SIZE: usize = 1 << 30; // 1GB max single allocation

impl SecurePool {
    pub fn new(slab_size: usize, audit_log: Box<dyn Fn(u64, &str)>) -> Self {
        SecurePool {
            slabs: RefCell::new(Vec::new()),
            allocations: RefCell::new(HashMap::new()),
            slab_size,
            next_id: RefCell::new(1),
            audit_log,
        }
    }

    /// Calculate total size needed including header and alignment padding
    /// Returns the aligned total size for the allocation
    fn calc_total_size(&self, requested_size: usize) -> Option<usize> {
        // Alignment to 16 bytes for SIMD compatibility
        let alignment: usize = 16;

        // Calculate header + data size using checked arithmetic throughout
        let header_and_data = HEADER_SIZE.checked_add(requested_size)?;

        // Verify the size fits in the header's u32 field for consistency
        if requested_size > u32::MAX as usize {
            return None;
        }

        // Align up: (size + alignment - 1) & !(alignment - 1)
        // All arithmetic stays in usize - no truncating casts
        let aligned = header_and_data.checked_add(alignment - 1)? & !(alignment - 1);

        Some(aligned)
    }

    /// Allocate a region in the secure pool
    pub fn alloc(&self, requested_size: usize) -> Option<u64> {
        if requested_size == 0 || requested_size > MAX_ALLOC_SIZE {
            return None;
        }

        let total_size = self.calc_total_size(requested_size)?;

        // Find a slab with enough space, or create a new one
        let mut slabs = self.slabs.borrow_mut();
        let mut allocations = self.allocations.borrow_mut();

        // Try to find space in existing slabs (simplified: just use new slab each time)
        let actual_slab_size = if total_size > self.slab_size {
            total_size
        } else {
            self.slab_size
        };

        let slab_index = slabs.len();
        slabs.push(vec![0u8; actual_slab_size]);

        // Write header at offset 0
        let slab = &mut slabs[slab_index];
        let header = AllocHeader {
            magic: MAGIC,
            user_size: requested_size as u32, // Safe: checked above that it fits
            alloc_id: 0, // Set below
            flags: 0,
        };

        let mut id = self.next_id.borrow_mut();
        let alloc_id = *id;
        *id += 1;
        drop(id);

        // Write header bytes
        let header_bytes: &[u8] = unsafe {
            std::slice::from_raw_parts(
                &header as *const AllocHeader as *const u8,
                HEADER_SIZE,
            )
        };
        slab[..HEADER_SIZE].copy_from_slice(header_bytes);

        // Record allocation with correct total_size
        allocations.insert(alloc_id, (slab_index, HEADER_SIZE, total_size - HEADER_SIZE));

        // Drop borrows before calling audit callback (prevents RefCell panic on reentry)
        drop(slabs);
        drop(allocations);

        // Audit log - safe to call here, all borrows released
        // Even if callback re-enters, state is consistent (alloc already recorded)
        (self.audit_log)(alloc_id, &format!("alloc:size={},total={}", requested_size, total_size));

        Some(alloc_id)
    }

    /// Read data from an allocation
    pub fn read(&self, alloc_id: u64, offset: usize, len: usize) -> Option<Vec<u8>> {
        let allocations = self.allocations.borrow();
        let (slab_idx, data_offset, data_len) = allocations.get(&alloc_id)?;

        // Bounds check against recorded length
        if offset.checked_add(len)? > *data_len {
            return None;
        }

        let slabs = self.slabs.borrow();
        let slab = slabs.get(*slab_idx)?;
        let start = data_offset.checked_add(offset)?;
        let end = start.checked_add(len)?;

        if end > slab.len() {
            return None;
        }

        Some(slab[start..end].to_vec())
    }

    /// Write data to an allocation
    pub fn write(&self, alloc_id: u64, offset: usize, data: &[u8]) -> bool {
        let allocations = self.allocations.borrow();
        let (slab_idx, data_offset, data_len) = match allocations.get(&alloc_id) {
            Some(v) => *v,
            None => return false,
        };

        // Bounds check
        let end_offset = match offset.checked_add(data.len()) {
            Some(v) => v,
            None => return false,
        };
        if end_offset > data_len {
            return false;
        }

        drop(allocations);

        let mut slabs = self.slabs.borrow_mut();
        let slab = match slabs.get_mut(slab_idx) {
            Some(s) => s,
            None => return false,
        };

        let start = match data_offset.checked_add(offset) {
            Some(v) => v,
            None => return false,
        };
        let end = match start.checked_add(data.len()) {
            Some(v) => v,
            None => return false,
        };
        if end > slab.len() {
            return false;
        }

        slab[start..end].copy_from_slice(data);

        drop(slabs);
        (self.audit_log)(alloc_id, "write");
        true
    }

    /// Free an allocation, zeroing the memory
    pub fn free(&self, alloc_id: u64) -> bool {
        let mut allocations = self.allocations.borrow_mut();
        let (slab_idx, data_offset, data_len) = match allocations.remove(&alloc_id) {
            Some(v) => v,
            None => return false,
        };
        drop(allocations);

        let mut slabs = self.slabs.borrow_mut();
        if let Some(slab) = slabs.get_mut(slab_idx) {
            // Zero out the entire allocation including header
            let start = data_offset.saturating_sub(HEADER_SIZE);
            let end = (data_offset + data_len).min(slab.len());
            for byte in &mut slab[start..end] {
                *byte = 0;
            }
        }
        drop(slabs);

        (self.audit_log)(alloc_id, "free");
        true
    }

    /// Get allocation metadata (for debugging/audit)
    pub fn get_info(&self, alloc_id: u64) -> Option<(usize, usize)> {
        let allocations = self.allocations.borrow();
        let (_, _, data_len) = allocations.get(&alloc_id)?;
        let slabs = self.slabs.borrow();
        Some((slabs.len(), *data_len))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::rc::Rc;
    use std::cell::Cell;

    #[test]
    fn test_basic_alloc_write_read() {
        let log_count = Rc::new(Cell::new(0u32));
        let lc = log_count.clone();
        let pool = SecurePool::new(4096, Box::new(move |_id, _msg| {
            lc.set(lc.get() + 1);
        }));

        let id = pool.alloc(100).unwrap();
        assert!(pool.write(id, 0, &[1, 2, 3, 4]));
        let data = pool.read(id, 0, 4).unwrap();
        assert_eq!(data, vec![1, 2, 3, 4]);
        assert!(pool.free(id));
        assert!(log_count.get() >= 2);
    }

    #[test]
    fn test_bounds_checking() {
        let pool = SecurePool::new(4096, Box::new(|_id, _msg| {}));
        let id = pool.alloc(100).unwrap();
        // Write beyond allocation should fail
        assert!(!pool.write(id, 90, &[0u8; 20]));
        // Read beyond allocation should fail
        assert!(pool.read(id, 90, 20).is_none());
        assert!(pool.free(id));
    }
}
